function applyFit(values){const items=artworkSelection();if(!items.length)return;const fit={...M.fitValues(values),...M.pinchValues({...fitTarget(),...values})};if(selected?.startsWith('group:')){const b=M.artworkBounds(items.map(l=>({...l,groupPose:undefined}))),old=items[0].groupPose,pose={...fit,x:old?.x??b.x+b.w/2,y:old?.y??b.y+b.h/2,w:old?.w??b.w,h:old?.h??b.h};items.forEach(l=>l.groupPose={...pose});}else if(items.length===1)Object.assign(items[0],fit);}
function fitPreview(p){const m=M.fitMatrix(p);m[4]=44-m[0]*22-m[2]*12;m[5]=27-m[1]*22-m[3]*12;return `<svg viewBox="0 0 88 56" aria-hidden="true"><rect class="fit-reference" x="22" y="15" width="44" height="24"/><g transform="matrix(${m.join(' ')})"><rect class="fit-surface" width="44" height="24" rx="2"/><path class="fit-stripe" d="M7 0H16L27 24H18Z"/><text x="31" y="17">27</text></g></svg>`;}
function fitFields(){const f={...M.fitValues(fitTarget()),...M.pinchValues(fitTarget())};return `<details class="fit-controls" ${fitPanelOpen?'open':''}><summary>Fit to angled view</summary><p class="note">Choose a starting angle, then adjust it to follow the car panel.</p><div class="fit-presets">${FIT_PRESETS.map(p=>`<button data-fit-preset="${p.id}" title="${p.name}: skew ${p.skewX||p.skewY}°, width ${Math.round(p.scaleX*100)}%, height ${Math.round(p.scaleY*100)}%">${fitPreview(p)}<span>${p.name}</span></button>`).join('')}</div>${[['skewX','Horizontal skew',-60,60,1,'°'],['skewY','Vertical skew',-60,60,1,'°'],['scaleX','Width compression',25,150,1,'%'],['scaleY','Height compression',25,150,1,'%']].map(([key,label,min,max,step,unit])=>{const value=Math.round(f[key]*(unit==='%'?100:1));return `<div class="fit-field"><label for="fit-${key}">${label}</label><div class="row"><input id="fit-${key}" data-fit-key="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><input data-fit-key="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label} ${unit}"><span>${unit}</span></div></div>`;}).join('')}<div class="pinch-section"><h3>Pinch the far end</h3><p class="note">Narrow one end to make the artwork recede. 0% keeps both ends equal.</p><div class="pinch-presets">${[['left','Left',-.35,0],['right','Right',.35,0],['top','Top',0,-.35],['bottom','Bottom',0,.35]].map(([id,label,x,y])=>{const m=M.pinchMatrix({pinchX:x,pinchY:y},{x:8,y:5,w:48,h:28}),points=[{x:8,y:5},{x:56,y:5},{x:56,y:33},{x:8,y:33}].map(p=>M.transformPoint(m,p));return `<button data-pinch-preset="${id}" title="Pinch ${label.toLowerCase()} end"><svg viewBox="0 0 64 38" aria-hidden="true"><polygon class="fit-surface" points="${points.map(p=>p.x+','+p.y).join(' ')}"/></svg>${label}</button>`;}).join('')}</div>${[['pinchX','Left (−) / Right (+)'],['pinchY','Top (−) / Bottom (+)']].map(([key,label])=>`<div class="fit-field"><label for="fit-${key}">${label}</label><div class="row"><input id="fit-${key}" data-fit-key="${key}" type="range" min="-80" max="80" value="${Math.round(f[key]*100)}"><input data-fit-key="${key}" type="number" min="-80" max="80" value="${Math.round(f[key]*100)}" aria-label="${label} pinch %"><span>%</span></div></div>`).join('')}<button class="wide quiet" data-action="reset-pinch">Reset pinch</button></div><button class="wide" data-action="reset-fit">Reset all fitting</button><p class="note">100% keeps the original proportions. These are 2D fitting guides; adjust placement to match your view.</p></details>`;}
