function updateFitInput(el){const key=el.dataset.fitKey,values={...M.fitValues(fitTarget()),...M.pinchValues(fitTarget())};values[key]=Number(el.value)/(key.startsWith('scale')||key.startsWith('pinch')?100:1);applyFit(values);document.querySelectorAll(`[data-fit-key="${key}"]`).forEach(input=>input.value=Math.round(({...M.fitValues(fitTarget()),...M.pinchValues(fitTarget())})[key]*(key.startsWith('scale')||key.startsWith('pinch')?100:1)));scheduleFitCanvas();}
