  if(add){const ids=new Set(selected?[]:paintRegions().map(r=>r.id)),items=paintRegions(key),remove=items.length&&items.every(r=>ids.has(r.id));items.forEach(r=>remove?ids.delete(r.id):ids.add(r.id));multiPaintSelected.clear();ids.forEach(id=>multiPaintSelected.add(id));selectedPaint=ids.size>1?'multi':ids.size?'r:'+ids.values().next().value:null;}
