  const key='g:'+name,open=expandedPaintGroups.has(name),visible=regions.some(r=>r.paintVisible!==false),colours=[...new Set(regions.map(r=>paintChip(M.paintOf(project,r))))],chip=colours.length===1?colours[0]:'repeating-linear-gradient(135deg,#96a3b0 0 4px,#e5484d 4px 8px)';
