  if(drag?.kind==='pan'&&viewBox.w===drag.box.w&&viewBox.h===drag.box.h){
    art.classList.add('panning');
    art.style.transform=`translate3d(${(drag.box.x-viewBox.x)*drag.scale}px,${(drag.box.y-viewBox.y)*drag.scale}px,0)`;
    art.style.cursor='grabbing';return;
  }
  art.classList.remove('panning');art.style.transform='';
  $('#welcome').hidden=!!project;$('#empty-view').hidden=!project||!!activeView();$('#view-badge').hidden=!activeView();$('#zoom-controls').hidden=!activeView();$('#view-badge').textContent=(M.LABELS[currentView]||'View').toUpperCase()+' VIEW';
  art.setAttribute('viewBox',`${viewBox.x} ${viewBox.y} ${viewBox.w} ${viewBox.h}`);$('#zoom-label').textContent=Math.round(100000/viewBox.w)+'%';
  art.style.cursor=drag?.kind==='pan'?'grabbing':tool==='hand'?'grab':['rect','ellipse','polygon','line','paint'].includes(tool)?'crosshair':'default';
  $('#mode-banner').hidden=!preparing;$('#mode-banner').textContent=tool==='polygon'?'Click around a region · Enter to finish · Esc to cancel':'Prepare template · Select a region and assign its role';
  if(!project){art.innerHTML='';return;}
  const canvasParts=V.renderViewParts(project,currentView,{id:'main',interactive:true,prepare:preparing,preview:true,effects:store.settings?.paintPreview!==false});let markup='';
  const l=selection();
  if(l&&!preparing){const matrix=M.layerMatrix(l),corner=M.transformPoint(matrix,{x:l.w,y:l.h}),r=screenUnits(4);markup+=`<polygon class="selection-box" points="${M.layerCorners(l).map(p=>p.x+','+p.y).join(' ')}"/><rect data-handle="resize" class="handle" x="${corner.x-r}" y="${corner.y-r}" width="${r*2}" height="${r*2}" style="cursor:nwse-resize"/>`;if(tool==='nodes'&&l.points)markup+=pathControls(M.mapPathPoints(l.points,p=>M.transformPoint(matrix,{x:p.x*l.w,y:p.y*l.h})),true);}

  if(!preparing&&!l&&artworkSelection().length){const b=M.artworkBounds(artworkSelection()),r=screenUnits(5);markup+=`<rect class="selection-box" pointer-events="none" x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}"/><rect data-group-resize="true" class="handle" x="${b.x+b.w-r}" y="${b.y+b.h-r}" width="${r*2}" height="${r*2}" style="cursor:nwse-resize"/>`;}
  const r=region();if(preparing&&r){const b=r.bounds;markup+=`<rect class="selection-box" x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}"/>`;}
  if(!preparing&&!selection()&&paintRegions().length){markup+='<g class="paint-selection" pointer-events="none">'+paintRegions().filter(r=>r.paintVisible!==false).map(r=>V.geometryMarkup(r,'outline')).join('')+'</g>';}
