function fillFields(p){const g=p.gradient||M.defaultGradient(p.fill);return `<div class="field"><label>Fill</label><div class="segmented"><button data-fill-type="solid" aria-pressed="${p.fillType!=='gradient'}">Solid</button><button data-fill-type="gradient" aria-pressed="${p.fillType==='gradient'}">Gradient</button></div></div>${p.fillType==='gradient'?`<div class="gradient-controls"><div class="gradient-preview" style="background:${gradientCSS(p)}"></div>${[['angle','Angle',360,'°',g.angle],['strength','Strength',100,'%',Math.round(g.strength*100)]].map(([key,label,max,unit,value])=>`<label class="gradient-range" for="gradient-${key}"><span>${label}</span><output data-gradient-output="${key}">${value}${unit}</output><input id="gradient-${key}" data-gradient-key="${key}" type="range" min="0" max="${max}" value="${value}" aria-label="Gradient ${label.toLowerCase()}"></label>`).join('')}<div class="gradient-stops">${g.stops.map((stop,i)=>`<div class="gradient-stop"><input type="color" data-stop-colour="${i}" value="${stop.colour}" aria-label="Colour stop ${i+1}"><input type="number" min="0" max="100" data-stop-offset="${i}" value="${Math.round(stop.offset*100)}" aria-label="Position of colour stop ${i+1}"><span>%</span><button data-remove-stop="${i}" ${g.stops.length<=2?'disabled':''} title="Remove colour stop ${i+1}" aria-label="Remove colour stop ${i+1}">×</button></div>`).join('')}</div><button class="wide" data-add-stop="true" ${g.stops.length>=8?'disabled':''}>+ Add colour stop</button><p class="note">Strength blends these colours with the base colour below. Up to 8 stops.</p></div>`:''}`;}
let gradientDraft=false;
function updateGradientInput(el){editGradient(g=>g[el.dataset.gradientKey]=Number(el.value)/(el.dataset.gradientKey==='strength'?100:1));const output=document.querySelector(`[data-gradient-output="${el.dataset.gradientKey}"]`);if(output)output.textContent=el.value+(el.dataset.gradientKey==='angle'?'°':'%');const preview=document.querySelector('.gradient-preview');if(preview)preview.style.background=gradientCSS(currentPaint());renderCanvas();renderViews();}
