function appearanceButtons(){const source=copyableAppearance();return `<div class="appearance-buttons"><button data-action="copy-appearance" ${source?'':'disabled'} title="${source?'Copy colour, gradient, finish and opacity; lines include stripe settings and text includes typeface.':'Select one artwork layer or a paint group with matching appearances.'}">Copy Appearance</button><button data-action="paste-appearance" ${canPasteAppearance()?'':'disabled'} title="${appearanceClipboard?'Apply compatible settings from '+e(appearanceClipboard.name):'Copy an appearance first.'}">Paste Appearance</button></div>`;}
