function dockInspector(){const box=document.querySelector('#inspector'),children=[...box.children],index=children.findIndex(n=>n.tagName==='H3'&&n.textContent.startsWith('Layers'));if(index<0)return;const props=document.createElement('div'),dock=document.createElement('section');props.className='property-scroll';dock.className='layers-dock';children.forEach((n,i)=>{if(i===index-1&&n.classList.contains('separator'))return;(i<index?props:dock).append(n);});box.replaceChildren(props,dock);box.classList.add('docked');organiseInspector(props);props.querySelector('.heading')?.insertAdjacentHTML('afterend',appearanceButtons());const controls=orderButtons();if(controls){const actions=dock.querySelector('.layer-actions');if(actions)actions.insertAdjacentHTML('beforebegin',controls);else dock.insertAdjacentHTML('beforeend',controls);}const tip=document.createElement('small');tip.className='layer-order-tip';tip.textContent='Shift-click to select several · Ctrl-click in Layers · Top = front · Drag rows to reorder'+(orderScope()?' · Within this group':'');dock.querySelector('h3')?.after(tip);}
