function pathControls(points,editable){const r=screenUnits(4.5);return points.map((p,i)=>{let markup='';for(const side of ['in','out'])if(p[side]){const h=p[side];markup+=`<line class="curve-arm" x1="${p.x}" y1="${p.y}" x2="${h.x}" y2="${h.y}"/><circle ${editable?`data-curve-handle="${i}" data-side="${side}"`:''} class="curve-handle" cx="${h.x}" cy="${h.y}" r="${r}"/>`;}return markup+`<circle ${editable?`data-point="${i}"`:''} class="draw-point ${editable&&selectedNode===i?'active-node':''} ${!editable&&i===0?'start-node':''}" cx="${p.x}" cy="${p.y}" r="${r}"/>`;}).join('');}
