async function fileData(file){if(file.size>10*1024*1024)throw new Error('Please use an image smaller than 10 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});if(!M.validImage(data))throw new Error('Use PNG, JPEG or WebP images.');const img=new Image();img.src=data;await img.decode();return {src:data,width:img.naturalWidth,height:img.naturalHeight};}
function importIsCurrent(p){return pendingAdd===p&&$('#dialog').open&&p.owner===project?.id;}
async function importCar(file){if(!pendingAdd)return;const p=pendingAdd;let view;if(p.kind==='svg'){const ext=file.name.split('.').pop().toLowerCase();if(['eps','pdf'].includes(ext)){await importVectorDocument(file,p);return;}if(ext!=='svg')throw new Error('Choose an SVG, EPS or PDF illustration.');if(file.size>5e6)throw new Error('Use an SVG smaller than 5 MB.');const text=await file.text();if(!importIsCurrent(p))return;view=V.importSVG(text);}else{const im=await fileData(file);if(!importIsCurrent(p))return;const s=Math.min(850/im.width,440/im.height);view={regions:[],bounds:{x:(1000-im.width*s)/2,y:(600-im.height*s)/2,w:im.width*s,h:im.height*s},source:'photo',showPhoto:true,photo:{src:im.src,x:(1000-im.width*s)/2,y:(600-im.height*s)/2,w:im.width*s,h:im.height*s}};}
  finishCarImport(p,view);}
async function importVectorDocument(file,p,page=null){
  try{
    if(file.size>25*1024*1024)throw new Error('Choose an EPS or PDF smaller than 25 MB.');
    openDialog('Preparing vector artwork',file.name,`<div class="import-info"><strong>Converting ${page?'page '+page:'your illustration'}…</strong><p class="note">This happens on your computer. Curves and outlines become selectable template regions.</p></div>`,`<button data-action="close-dialog">Cancel import</button>`);
    const result=await window.desktop.convertVector({format:file.name.split('.').pop().toLowerCase(),bytes:new Uint8Array(await file.arrayBuffer()),page});
    if(!importIsCurrent(p))return;
    if(!result.svg){
      openDialog('Choose a page',file.name,`<p>This document has ${result.pages} pages. Import the page containing the view you want to prepare.</p><div class="field"><label for="vector-page">Page number</label><input id="vector-page" type="number" min="1" max="${result.pages}" step="1" value="1"></div><p class="note">You can import another page later as another view.</p>`,`<button data-action="close-dialog">Cancel</button><button class="primary" id="import-vector-page">Import page</button>`);
      $('#import-vector-page').onclick=()=>{const value=Number($('#vector-page').value);if(!Number.isInteger(value)||value<1||value>result.pages)return toast(`Choose a page from 1 to ${result.pages}.`);importVectorDocument(file,p,value).catch(reportError);};return;
    }
    finishCarImport(p,V.importSVG(result.svg));
  }catch(error){if(importIsCurrent(p)){addCarDialog(p.view,p.replace);$('#car-name').value=p.name;$('#car-scale').value=p.scale;$('#car-view').value=p.key;}throw error;}
}
function finishCarImport(p,view){
  if(!importIsCurrent(p))return;
  if(p.kind==='svg')view={...view,regions:[],vectorSource:M.clone(view)};
  if(p.view){record();project.template.views[p.key]=view;if(p.replace)project.views[p.key]=[];}else{const template={id:M.uid(),name:p.name,scale:p.scale,views:{[p.key]:view},creator:'',description:'',updated:new Date().toISOString()};store.templates.push(M.clone(template));setProject(M.newProject(template));}
  currentView=p.key;preparing=true;selected=null;selectedRegion=view.regions.find(r=>r.role==='body')?.id||null;tool='select';drawPoints=[];closeDialog();pendingAdd=null;fit();changed();render();toast(p.kind==='svg'?'Choose the panels you want to paint.':'Photograph added. Trace a body outline to begin.');if(p.kind==='svg')choosePaintablePanels();}
async function addImage(file){if(/\.(svg|eps|pdf|sfsheet|sfdecal)$/i.test(file.name))return window.DecalImport.open(file);const im=await fileData(file),asset={id:M.uid(),name:file.name.replace(/\.[^.]+$/,''),type:'image',src:im.src,width:im.width,height:im.height};store.assets.push(asset);scheduleSave();if(project){const w=Math.min(240,im.width),h=w*im.height/im.width;addLayer(M.layer('image',{name:asset.name,src:im.src,x:500-w/2,y:300-h/2,w,h}));toast('Image added to your artwork and library.');}else{toast('Image saved to your library.');openLibrary('assets');}}
