function openPackageExport(){packagePage=0;packageChoices=new Set();packageTab='templates';openDialog('Export a package','Choose the items to share. Their editable elements, images and custom fonts are included.',`<div class="library-toolbar"><div class="tabs">${packageTabs.map(([key,name])=>`<button data-package-tab="${key}">${name} <small>${store[key].length}</small></button>`).join('')}</div><div class="row library-controls"><input id="package-search" placeholder="Find items to share…" aria-label="Find items to share"><button id="package-select-shown">Select shown</button><button id="package-clear">Clear all</button></div><p class="note">Selections stay selected when you change tabs or search. A project includes its own car template.</p></div><div id="package-items"></div>`,`<div class="package-summary"><label for="package-name">Package name</label><input id="package-name" value="My Livery collection" maxlength="100"><small id="package-count" role="status"></small></div><button data-action="sharing">Back</button><button id="package-export" class="primary" disabled>${icon('share')}Export package</button>`);$('#dialog').classList.add('package-dialog');$('#package-search').oninput=()=>{packagePage=0;renderPackageItems();};document.querySelectorAll('[data-package-tab]').forEach(b=>b.onclick=()=>{packageTab=b.dataset.packageTab;packagePage=0;renderPackageItems();});$('#package-select-shown').onclick=()=>{pageSlice(packageItems(),packagePage).forEach(a=>packageChoices.add(packageTab+':'+a.id));renderPackageItems();};$('#package-clear').onclick=()=>{packageChoices.clear();renderPackageItems();};$('#package-export').onclick=exportChosenPackage;renderPackageItems();}
