function updatePackageCount(){const counts=packageTabs.map(([k,n])=>{const count=store[k].filter(a=>packageChoices.has(k+':'+a.id)).length;const names={templates:['car','cars'],liveries:['livery','liveries'],assets:['artwork item','artwork items'],projects:['project','projects'],fonts:['font','fonts']}[k];return count?`${count} ${names[count===1?0:1]}`:'';}).filter(Boolean);$('#package-count').textContent=counts.length?counts.join(' · '):'No items selected';$('#package-export').disabled=!packageChoices.size;}
function renderPackageItems(){
 document.querySelectorAll('[data-package-tab]').forEach(b=>b.classList.toggle('active',b.dataset.packageTab===packageTab));const items=packageItems();packagePage=Math.min(packagePage,Math.max(0,Math.ceil(items.length/LIBRARY_PAGE_SIZE)-1));
 $('#package-items').innerHTML=items.length?'<div class="library-grid">'+pageSlice(items,packagePage).map(a=>{const key=packageTab+':'+a.id;return '<label class="library-card package-card '+(packageChoices.has(key)?'selected':'')+'"><div class="package-check"><input type="checkbox" data-package-item="'+e(key)+'" '+(packageChoices.has(key)?'checked':'')+'><span>'+e(a.name)+'</span></div>'+cardPreview(a,packageTab)+'<small>Editable library item</small></label>';}).join('')+'</div>'+paging(items,packagePage,'package'):'<div class="empty-library"><h3>No matching items</h3><p>Try another category or search.</p></div>';
 document.querySelectorAll('[data-package-item]').forEach(c=>c.onchange=()=>{c.checked?packageChoices.add(c.dataset.packageItem):packageChoices.delete(c.dataset.packageItem);c.closest('.package-card').classList.toggle('selected',c.checked);updatePackageCount();});updatePackageCount();loadCardPreviews().catch(reportError);
}
async function exportChosenPackage(){if(!packageChoices.size)return;const button=$('#package-export');button.disabled=true;try{const data=Object.fromEntries(packageTabs.map(([key])=>[key,store[key].filter(a=>packageChoices.has(key+':'+a.id))]));await exportPackage('library',data,M.name($('#package-name').value,'Livery collection'));}catch(error){reportError(error);}finally{if(button.isConnected)button.disabled=false;}}
async function exportPackage(kind,data,name){data=await libraryClient.materialize(store,data);const pkg={format:'slotforge-paintshop',version:1,kind,exported:new Date().toISOString(),data:M.clone(data)};if(new Blob([JSON.stringify(pkg,null,2)]).size>180*1024*1024)throw new Error('Package exceeds 180 MB. Export fewer items at a time.');if(window.desktop){if(await window.desktop.exportPackage({name,data:pkg}))toast('Package exported.');}else{download(new Blob([JSON.stringify(pkg,null,2)],{type:'application/json'}),name+'.sfpaint');toast('Package downloaded.');}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function validateTemplate(t,allowEmpty=false){if(!t||!t.views||typeof t.views!=='object')throw new Error('Missing car views.');const views={};for(const k of M.VIEWS)if(t.views[k])views[k]=V.validateView(t.views[k]);if(allowEmpty!==true&&!Object.keys(views).length)throw new Error('Car needs at least one view.');return {id:M.uid(),name:M.name(t.name,'Imported car'),scale:M.name(t.scale,''),views,creator:M.name(t.creator,''),description:String(t.description||'').slice(0,2000),updated:new Date().toISOString()};}
function validateLivery(l){if(!l||!l.views)throw new Error('Missing livery artwork.');const views={};for(const k of M.VIEWS){if(l.views[k]&&!Array.isArray(l.views[k]))throw new Error('Invalid livery layers.');views[k]=(l.views[k]||[]).map(M.validateLayer);}const bounds={};for(const k of M.VIEWS){const b=l.bounds?.[k]||{x:0,y:0,w:1000,h:600};bounds[k]={x:M.number(b.x),y:M.number(b.y),w:M.number(b.w,1000,1,10000),h:M.number(b.h,600,1,10000)};}return {id:M.uid(),name:M.name(l.name,'Imported livery'),...libraryMetadata(l),base:M.colour(l.base,'#ffffff'),finish:M.FINISHES.includes(l.finish)?l.finish:'Gloss',effect:M.EFFECTS.includes(l.effect)?l.effect:'Solid',...M.fillSettings(l),panelPaints:M.validatePanelPaints(l.panelPaints),views,bounds,notes:String(l.notes||'').slice(0,12000),paints:String(l.paints||'').slice(0,12000),updated:new Date().toISOString()};}
function validateAsset(a){if(!a||!['image','shape','group'].includes(a.type))throw new Error('Unsupported library asset.');if(a.type==='image'){if(!M.validImage(a.src))throw new Error('Invalid image asset.');return {id:M.uid(),name:M.name(a.name),...libraryMetadata(a),type:'image',src:a.src,width:M.number(a.width,240,1,20000),height:M.number(a.height,100,1,20000)};}if(a.type==='group'){if(!Array.isArray(a.layers)||!a.layers.length)throw new Error('A group needs at least one editable element.');return {...M.groupAsset(a.layers.map(M.validateLayer),a.name),...libraryMetadata(a)};}return {id:M.uid(),name:M.name(a.name),...libraryMetadata(a),type:'shape',layer:stripGroup(M.validateLayer(a.layer))};}
function validateFontAsset(a){return {id:M.uid(),name:M.name(a.name),...libraryMetadata(a),fontData:M.validateFontData(a.fontData)};}
function validateProject(p){const t=validateTemplate(p.template,true),l=validateLivery(p);return {...l,template:t,id:M.uid()};}
async function readPackage(file){if(file.size>180*1024*1024)throw new Error('Package exceeds the 180 MB import limit.');const pkg=JSON.parse(await file.text());if(pkg.format!=='slotforge-paintshop'||pkg.version!==1)throw new Error('This is not a supported Livery package.');const additions={templates:[],liveries:[],assets:[],fonts:[],projects:[]};const map={template:['templates',validateTemplate],livery:['liveries',validateLivery],asset:['assets',validateAsset],project:['projects',validateProject],font:['fonts',validateFontAsset]};if(pkg.kind==='library'){for(const [key,fn] of [['templates',validateTemplate],['liveries',validateLivery],['assets',validateAsset],['projects',validateProject],['fonts',validateFontAsset]]){if(key==='fonts'&&pkg.data?.fonts===undefined)continue;if(!Array.isArray(pkg.data?.[key]))throw new Error('Invalid library package.');additions[key]=pkg.data[key].map(fn);}}else{const spec=map[pkg.kind];if(!spec)throw new Error('Unknown package type.');additions[spec[0]].push(spec[1](pkg.data));}await FontLibrary.loadAll(additions);pendingPackage=additions;openDialog('Import this package?','All items are added as independent copies. Existing items are kept.',`<div class="import-info"><strong>${e(file.name)}</strong><p style="margin:12px 0 0">${Object.entries(additions).filter(([k,v])=>v.length).map(([k,v])=>`${v.length} ${k}`).join(' · ')}</p></div><p class="note" style="margin-top:15px">Artwork is checked before import. Scripts and external resources are excluded; vector decals retain supported gradients, clipping and embedded images.</p>`,`<button data-action="close-dialog">Cancel</button><button class="primary" data-action="confirm-import">Import items</button>`);pendingPackage=additions;}
async function importConfirmed(){
  const a=pendingPackage;if(!a)return;
  const recovering=loadBlocked,next=recovering?M.clone(store):null,button=document.querySelector('[data-action="confirm-import"]');
  if(recovering)for(const k of Object.keys(a))next[k].push(...a[k]);
  if(button)button.disabled=true;
  try{
    if(recovering){
      clearTimeout(saveTimer);await savePromise.catch(()=>{});
      if(window.desktop){const restored=await window.desktop.restore(next);libraryClient.accept(restored);}
      else{const old=localStorage.getItem('slotforge-paintshop-v1');if(old)localStorage.setItem('slotforge-paintshop-recovery-'+Date.now(),old);localStorage.setItem('slotforge-paintshop-v1',JSON.stringify(next));}
      store=next;project=store.projects.find(p=>p.id===project?.id)||null;loadBlocked=false;
    }else for(const k of Object.keys(a))store[k].push(...a[k]);
    pendingPackage=null;closeDialog();
    if(a.projects.length)setProject(store.projects.find(p=>p.id===a.projects[0].id));else openLibrary(a.templates.length?'templates':a.liveries.length?'liveries':a.fonts?.length?'fonts':'assets');
    scheduleSave();await flushSave();
    toast(recovering?'Backup restored and saved. Previous files were preserved.':'Items imported. Your existing library was kept.');
  }catch(error){reportError(error);}finally{if(button?.isConnected)button.disabled=false;}
}
function notesDialog(){if(!project)return;openDialog('Workshop notes','These details are included in the PDF and saved livery.',`<div class="field"><label for="paint-notes">Paint references</label><textarea id="paint-notes" placeholder="e.g. Body blue: brand and product code\nOrange stripe: brand and product code">${e(project.paints)}</textarea></div><div class="field"><label for="workshop-notes">Masking, decals and application notes</label><textarea id="workshop-notes" style="min-height:150px" placeholder="Record your intended painting order, masking boundaries and decal placement notes…">${e(project.notes)}</textarea></div><p class="note">Screen and print colours are approximate. Use the actual paint reference for your workshop decisions.</p>`,`<button data-action="close-dialog">Cancel</button><button id="notes-save" class="primary">Save notes</button>`);$('#notes-save').onclick=()=>{const paints=$('#paint-notes').value,notes=$('#workshop-notes').value;mutate(()=>{project.paints=paints;project.notes=notes;});closeDialog();};}
function reportPaint(c){const swatch=colour=>`<span class="swatch" style="background:${colour}"></span>${colour.toUpperCase()}`;return swatch(c.fill)+(c.fillType==='gradient'&&c.gradient?`<br>Gradient · ${c.gradient.angle}° · ${Math.round(c.gradient.strength*100)}% strength<br>${c.gradient.stops.map(s=>swatch(s.colour)+' at '+Math.round(s.offset*100)+'%').join('<br>')}`:'');}
function makeReport(){const p=project,used=new Map(),add=(name,paint)=>used.set(name+JSON.stringify(paint),{name,...paint});add('Base paint',M.paintOf(p));for(const k of M.VIEWS)for(const l of p.views[k])if(!['image','vector'].includes(l.kind)){add(l.name,M.paintOf(l));if(l.kind==='line')l.lineStripes.forEach((s,i)=>{if(s.colour)add(l.name+' · stripe '+(i+1),{...M.paintOf(l),fill:s.colour,fillType:'solid'});});}for(const v of Object.values(p.template.views))for(const r of v.regions)if(r.role==='body')add(r.partLabel||r.name,M.paintOf(p,r));
  const css='@page{size:A4 portrait;margin:14mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#1f2a35;margin:0}h1{font-size:26px;margin:8px 0}h2{font-size:18px;margin:18px 0 8px}small,p{color:#596573;line-height:1.6}.brand{font-size:11px;letter-spacing:2px;color:#d84149}header{border-bottom:3px solid #d84149;padding-bottom:14px}.sheet{break-after:page}.sheet:last-child{break-after:auto}.car{height:105mm;width:100%;background:#f3f5f7;margin:14px 0;border:1px solid #dce2e8}.car svg{width:100%;height:100%}table{border-collapse:collapse;width:100%;font-size:11px}td,th{border-bottom:1px solid #ddd;padding:8px;text-align:left}.swatch{display:inline-block;width:20px;height:14px;border:1px solid #bbb;vertical-align:middle;margin-right:8px}pre{white-space:pre-wrap;font:12px/1.7 Arial;color:#333;overflow-wrap:anywhere}.note{font-size:10px;color:#777}.art-list{font-size:11px;line-height:1.7}';
  return `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:;"><title>${e(p.name)}</title><style>${css}</style></head><body><section class="sheet"><header><div class="brand">SLOTFORGE LIVERY · WORKSHOP PLAN</div><h1>${e(p.name)}</h1><p>${e(p.template.name)} · ${e(p.template.scale)} · ${new Date().toLocaleDateString()}</p></header><h2>Paint & finish references</h2><table><tr><th>Use</th><th>Colour</th><th>Effect</th><th>Finish</th></tr>${[...used.values()].map(c=>`<tr><td>${e(c.name)}</td><td>${reportPaint(c)}</td><td>${e(c.effect)}</td><td>${e(c.finish)}</td></tr>`).join('')}</table><h2>Paint products</h2><pre>${e(p.paints||'No product references entered.')}</pre><h2>Workshop notes</h2><pre>${e(p.notes||'No additional notes entered.')}</pre><p class="note">Reference plan only. Views are not printed at actual scale and are not cutting or decal-wrap templates. Printed colours and illustrative finishes are approximate.</p></section>${M.VIEWS.filter(k=>p.template.views[k]).map(k=>`<section class="sheet"><header><div class="brand">SLOTFORGE LIVERY · ${M.LABELS[k].toUpperCase()} VIEW</div><h2>${e(p.name)}</h2><small>${e(p.template.name)}</small></header><div class="car">${V.standalone(p,k,'report-'+k)}</div><h2>Artwork placement</h2><div class="art-list">${p.views[k].filter(l=>l.visible!==false).map(l=>`${e(l.name)}${['image','vector'].includes(l.kind)?' · '+l.kind+' decal':` · ${e(l.effect)} / ${e(l.finish)}`}`).join('<br>')||'Base paint only.'}</div><p class="note">${M.LABELS[k]} view · Design reference, not actual size. Check placement against the physical shell.</p></section>`).join('')}</body></html>`;
}
async function preparePrintableReport(html){
  // PDF vector compositing does not preserve the additive coverage at mesh seams.
  // Rasterise only views using perspective, at a resolution above 300 dpi on A4.
  const doc=new DOMParser().parseFromString(html,'text/html');
  for(const svg of doc.querySelectorAll('.car > svg')){
    if(!svg.querySelector('[id^="warp-"],style'))continue;
    svg.setAttribute('width','3000');svg.setAttribute('height','1800');
    const source=new XMLSerializer().serializeToString(svg),img=new Image();
    img.src='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(source)));
    await img.decode();const canvas=document.createElement('canvas');canvas.width=3000;canvas.height=1800;canvas.getContext('2d').drawImage(img,0,0,3000,1800);
    const output=doc.createElement('img');output.src=canvas.toDataURL('image/png');output.alt='Workshop design view';output.style.cssText='width:100%;height:100%;object-fit:contain';svg.replaceWith(output);
  }
  return '<!doctype html>'+doc.documentElement.outerHTML;
}
async function rasterSVG(source,width,height){const img=new Image();img.src='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(source)));await img.decode();const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(img,0,0,width,height);return canvas;}
async function pngArtwork(projectSnapshot,key,effects=false){
  const source=V.standalone(projectSnapshot,key,'png-export',{effects}),canvas=await rasterSVG(source,1000,600),pixels=canvas.getContext('2d').getImageData(0,0,1000,600).data;
  let left=1000,top=600,right=-1,bottom=-1;
  for(let y=0;y<600;y++)for(let x=0;x<1000;x++)if(pixels[(y*1000+x)*4+3]){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}
  if(right<left)throw new Error('This view has no visible artwork to export.');
  // One source pixel of transparent margin keeps antialiased outlines inside the crop.
  return {source,bounds:{x:left-1,y:top-1,w:right-left+3,h:bottom-top+3}};
}
async function renderPNG(artwork,size){const b=artwork.bounds,scale=size/Math.max(b.w,b.h),width=Math.max(1,Math.round(b.w*scale)),height=Math.max(1,Math.round(b.h*scale));const doc=new DOMParser().parseFromString(artwork.source,'image/svg+xml'),svg=doc.documentElement;svg.setAttribute('viewBox',`${b.x} ${b.y} ${b.w} ${b.h}`);svg.setAttribute('width',width);svg.setAttribute('height',height);return rasterSVG(new XMLSerializer().serializeToString(svg),width,height);}
function exportPNGDialog(){
  if(!project||!Object.keys(project.template.views).length)return toast('Add a car view before exporting.');
  const snapshot=M.clone(project),views=M.VIEWS.filter(k=>snapshot.template.views[k]),initial=views.includes(currentView)?currentView:views[0];
  openDialog('Export transparent PNG','A freestanding image of one car view, cropped to the visible artwork.',`<div class="row"><div class="field"><label for="png-view">Car view</label><select id="png-view">${views.map(k=>`<option value="${k}" ${k===initial?'selected':''}>${M.LABELS[k]}</option>`).join('')}</select></div><div class="field"><label for="png-size">Longest edge</label><select id="png-size">${[1000,2000,3000,4000].map(n=>`<option value="${n}" ${n===2000?'selected':''}>${n} px</option>`).join('')}</select></div></div><label class="checkbox-line"><input id="png-effects" type="checkbox" ${store.settings?.paintPreview!==false?'checked':''}>Include paint finish preview</label><div class="png-preview" id="png-preview"></div><p class="note" id="png-info" role="status">Preparing preview…</p><p class="note">The checkerboard shows transparency. Canvas, selection outlines and photo tracing guides are excluded. Backgrounds drawn into the imported artwork remain part of it.</p>`,`<button data-action="close-dialog">Cancel</button><button id="png-save" class="primary" disabled>Save PNG</button>`);
  const button=$('#png-save'),preview=$('#png-preview'),info=$('#png-info');let sequence=0,prepared=null,saving=false;
  const refresh=async()=>{const ticket=++sequence;button.disabled=true;prepared=null;try{const key=$('#png-view').value,effects=$('#png-effects').checked,size=Number($('#png-size').value),artwork=await pngArtwork(snapshot,key,effects);const canvas=await renderPNG(artwork,Math.min(size,1000));if(ticket!==sequence||!button.isConnected)return;preview.replaceChildren(canvas);prepared={key,size,artwork};const b=artwork.bounds,scale=size/Math.max(b.w,b.h);info.textContent=`${Math.round(b.w*scale)} × ${Math.round(b.h*scale)} pixels · Transparent PNG`;button.disabled=saving;}catch(error){if(ticket===sequence&&button.isConnected){preview.replaceChildren();info.textContent=error.message;}}};
  for(const id of ['png-view','png-size','png-effects'])$('#'+id).onchange=refresh;
  button.onclick=async()=>{if(!prepared||saving)return;saving=true;button.disabled=true;const job=prepared,ticket=sequence,current=()=>button.isConnected&&$('#dialog').open&&ticket===sequence;try{const canvas=await renderPNG(job.artwork,job.size),name=snapshot.name+'-'+M.LABELS[job.key];if(!current())return;if(window.desktop){if(await window.desktop.exportPNG({name,dataURL:canvas.toDataURL('image/png')})){if(current())closeDialog();toast('Transparent PNG saved.');}}else{const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!current())return;download(blob,name+'.png');closeDialog();toast('Transparent PNG downloaded.');}}catch(error){reportError(error);}finally{saving=false;if(button.isConnected)button.disabled=!prepared;}};
  refresh();
}
async function exportPDF(){if(!project)return;if(!Object.values(project.template.views).some(v=>v.regions.some(r=>r.role==='body')))return toast('Prepare a paintable body before exporting.');toast('Preparing your workshop PDF…');const html=await preparePrintableReport(makeReport());if(window.desktop){if(await window.desktop.exportPDF({name:project.name,html}))toast('Workshop PDF saved.');}else{download(new Blob([html],{type:'text/html'}),project.name+'-workshop.html');toast('Workshop report downloaded. Open it and choose Print → Save as PDF.');}}
function shapesDialog(){openDialog('Add a shape','Start with a familiar shape, then adjust it on the car.',`<div class="choice-grid">${[['rect','Rectangle / stripe'],['ellipse','Roundel'],['diagonal','Diagonal band'],['chevron','Chevron']].map(([k,n])=>`<button class="choice-card" data-preset="${k}">${icon(k==='ellipse'?'ellipse':'rect')}<strong>${n}</strong><small>Editable colour, position and size</small></button>`).join('')}</div><button data-action="custom-shape">${icon('pen')}Draw my own shape</button>`);}
function addPreset(kind){closeDialog();let l=M.layer(kind==='ellipse'?'ellipse':'rect',{fill:colour});if(kind==='ellipse'){l.w=90;l.h=90;l.name='Roundel';}if(kind==='diagonal')l=M.layer('polygon',{fill:colour,name:'Diagonal stripe',points:[{x:.3,y:0},{x:1,y:0},{x:.7,y:1},{x:0,y:1}]});if(kind==='chevron')l=M.layer('polygon',{fill:colour,name:'Chevron',points:[{x:0,y:0},{x:.65,y:0},{x:1,y:.5},{x:.65,y:1},{x:0,y:1},{x:.35,y:.5}]});addLayer(l);}
function helpDialog(){openDialog('A quick tour','SlotForge Livery · v1.3.0',`<div class="help-grid"><div><h3>1. Bring your own car</h3><p>Import SVG, EPS or vector PDF artwork, or a PNG/JPG/WebP photograph. Choose a page for multi-page PDFs. Select a view. Each view is independent; an angled photo does not generate other angles.</p><h3>2. Prepare the template</h3><p>For vector files, click the panels you want to paint in the chooser. Only selected panels become editable regions. Reopen Choose paintable panels to adjust the selection. Generate all vector regions is an optional preparation tool for detailed Body, Protect, Detail and Hide assignments. Photos use manual point tracing. Press Enter to close a traced shape.</p><h3>3. Paint & personalise</h3><p>Paint the base, drag rectangles and ellipses, draw curved shapes, add numbers or import SVG/EPS/PDF decals and transparent PNG images with Import decal artwork (I). Import a .sfsheet or .sfdecal file from SlotForge Decals to choose separate decals. For PDF or SVG sheets, enable Select separate decals and draw crop boxes. Imported vector graphics retain their original appearance; their internal text and paths are not Livery editing tools. Use Line (L) to draw open Bézier lines: click for corners, click-drag for curve handles, then Enter, Esc, right-click or Finish line to finish without closing the path. Use Cancel to discard the draft. Choose a stripe preset, then edit thickness, gaps, individual colours and flat/rounded ends. Each line remains an editable layer, and Add to Library saves its stripe settings. Shift-click car areas or shapes on the canvas to add or remove them from a selection. Shift-click or Ctrl-click rows in Layers also selects several; click a label row to select its areas together. Colour, gradient, finish and paint effect controls apply to every selected paintable area or shape. Ctrl-drag continues to pan the canvas. Select and drag artwork to move it; use its bottom-right handle to resize. Click for a corner or click-drag for smooth curve handles. Click near the starting point to close the shape. Use Edit points & curves (A) to adjust anchors and handles later. Open Fit to angled view for skew, compression and pinch controls. Pinch Left, Right, Top or Bottom to narrow the far end; use the sliders for the amount. Reset pinch keeps the skew; Reset all fitting clears both. Groups fit together while retaining editable elements. Scale a group or multi-selection with its corner handle, linked Width/Height or Scale percentage. Line widths and spacing scale with the group. Fine-tune size and rotation in the inspector. Copy Appearance takes a snapshot of one layer’s styling; Paste Appearance applies compatible paint, finish, opacity, line stripe or typeface settings to the selected layers. It keeps their content and fitting, and supports Undo.</p></div><div><h3>4. Reuse & share</h3><p>Shapes stay in your project until you click Add to Library. Shift-click shapes or layer rows to save several as an editable group. Expand a group in Layers to edit its children. Import TTF, OTF, WOFF or WOFF2 files through User Library → Fonts, or Import font beside the text typeface menu. Fonts stay inside Livery and travel with text in shared designs. Apply a saved livery to another car, then adjust the fit. Export .sfpaint packages or a complete library backup. Imports never overwrite existing items.</p><h3>5. Take it to the workshop</h3><p>Add paint product references and notes, then export a PDF. Export PNG saves a cropped, transparent image of a chosen view at 1,000–4,000 pixels, with optional paint finish preview. Matte, satin, gloss, metallic and pearl have optional subtle on-screen cues. Toggle Finish preview above the canvas. Choose Solid or Gradient for paint and shapes; gradients support 2–8 colour stops, positions, angle and strength. PDFs include the gradient colours and paint instructions without the preview sheen. The PDF is a reference, not a calibrated cutting pattern.</p><h3>Keyboard shortcuts</h3><p><span class="shortcut">V</span> Select · <span class="shortcut">A</span> Edit points & curves<br><span class="shortcut">R</span> Rectangle · <span class="shortcut">E</span> Ellipse<br><span class="shortcut">P</span> Polygon · <span class="shortcut">L</span> Line<br><span class="shortcut">T</span> Text<br><span class="shortcut">H</span> Pan · wheel to zoom · middle-drag or Ctrl + left-drag to pan<br><span class="shortcut">Ctrl Z</span> Undo · <span class="shortcut">Ctrl Shift Z</span> Redo<br><span class="shortcut">Ctrl D</span> Duplicate · <span class="shortcut">Delete</span> Remove<br><span class="shortcut">Ctrl S</span> Save project</p></div></div><div class="inline-note">Your library is stored on this computer. Use Import & Export → Back up my library for a portable copy. No account, cloud upload or API key is needed.</div>`);}
