 'close-dialog':closeDialog,help:helpDialog,studio:()=>showSettings(false),settings:()=>showSettings(),projects:()=>{if(settingsOpen)showSettings(false);openProjects();},library:()=>{if(settingsOpen)showSettings(false);openLibrary();},sharing:()=>{if(settingsOpen)showSettings(false);openSharing();},
 'add-car':()=>addCarDialog(),'add-view':()=>project&&addCarDialog(currentView||'left'),import:()=>$('#package-file').click(),'confirm-import':importConfirmed,
 'export-selection':()=>openPackageExport(),
 'export-all':()=>exportPackage('library',store,'SlotForge Livery Library'),
 'export-project':()=>project&&exportPackage('project',project,project.name),
