 'save-livery':()=>{if(!project)return toast('Create a project first.');askName('Save a reusable livery',project.name,n=>{store.liveries.push(M.liveryFromProject(project,n));scheduleSave();toast('Livery saved to your library.');});},
 'copy-appearance':copyAppearance,'paste-appearance':pasteAppearance,
